#include "htb/engine.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#undef assert
#define assert(condition) do { if (!(condition)) { fprintf(stderr,"CHECK failed: %s (%s:%d)\n",#condition,__FILE__,__LINE__); abort(); } } while(0)

static void parse(htb_scalar*x,const char*s){char e[160]={0};assert(htb_scalar_parse_rational(x,s,e,sizeof(e)));}
static void configure_tiling(htb_tiling_config*c,const char*cx,const char*cy){memset(c,0,sizeof(*c));snprintf(c->id,sizeof(c->id),"elliptical-square");snprintf(c->version,sizeof(c->version),"1");c->parameter_count=2;snprintf(c->parameters[0].key,sizeof(c->parameters[0].key),"centerX");snprintf(c->parameters[0].value,sizeof(c->parameters[0].value),"%s",cx);snprintf(c->parameters[1].key,sizeof(c->parameters[1].key),"centerY");snprintf(c->parameters[1].value,sizeof(c->parameters[1].value),"%s",cy);}
static void configure_order5(htb_tiling_config*c,const char*u,const char*v){memset(c,0,sizeof(*c));snprintf(c->id,sizeof(c->id),"order5-square");snprintf(c->version,sizeof(c->version),"1");c->parameter_count=2;snprintf(c->parameters[0].key,sizeof(c->parameters[0].key),"centerU");snprintf(c->parameters[0].value,sizeof(c->parameters[0].value),"%s",u);snprintf(c->parameters[1].key,sizeof(c->parameters[1].key),"centerV");snprintf(c->parameters[1].value,sizeof(c->parameters[1].value),"%s",v);}
static void configure_binary(htb_tiling_config*c){memset(c,0,sizeof(*c));snprintf(c->id,sizeof(c->id),"binary");snprintf(c->version,sizeof(c->version),"1");}

static void test_tiling_provider(htb_backend_kind kind){
    htb_arith_ctx ctx;char error[256]={0};assert(htb_arith_ctx_init(&ctx,kind,256,2048,error,sizeof(error)));htb_tiling_config config;configure_tiling(&config,"1/2","-2/3");htb_tiling tiling;assert(htb_tiling_init(&tiling,&ctx,&config,error,sizeof(error)));
    htb_vec2 reference,disk,roundtrip,n,v,out;htb_vec2_init(&ctx,&reference);htb_vec2_init(&ctx,&disk);htb_vec2_init(&ctx,&roundtrip);htb_vec2_init(&ctx,&n);htb_vec2_init(&ctx,&v);htb_vec2_init(&ctx,&out);parse(&reference.x,"7/3");parse(&reference.y,"-5/4");assert(tiling.definition->ops.from_reference(&tiling,&reference,&disk,error,sizeof(error)));assert(tiling.definition->ops.to_reference(&tiling,&disk,&roundtrip,error,sizeof(error)));assert(fabs(htb_scalar_get_approx(&roundtrip.x)-7.0/3.0)<1e-20);assert(fabs(htb_scalar_get_approx(&roundtrip.y)+1.25)<1e-20);
    htb_point_location location;htb_point_location_init(&location);assert(tiling.definition->ops.locate_point(&tiling,&disk,&location,error,sizeof(error)));assert(strcmp(location.tile.key,"elliptical-square:2,-2")==0);assert(location.tile.coordinate_count==2&&location.tile.coordinates[0]==2&&location.tile.coordinates[1]==-2);htb_adjacency_list neighbors;htb_adjacency_list_init(&neighbors);assert(htb_tiling_neighbors(&tiling,&location.tile,&neighbors,error,sizeof(error)));assert(neighbors.count==4);for(size_t i=0;i<neighbors.count;i++){htb_adjacency reverse;assert(tiling.definition->ops.adjacent(&tiling,&neighbors.items[i].neighbor,&neighbors.items[i].neighbor_edge,&reverse,error,sizeof(error)));assert(htb_tile_id_equal(&reverse.neighbor,&location.tile));assert(strcmp(reverse.source_edge.boundary_key,neighbors.items[i].source_edge.boundary_key)==0);}
    parse(&v.x,"2");parse(&v.y,"3");assert(tiling.definition->ops.normal_at(&tiling,&neighbors.items[0].source_edge,&disk,&n,error,sizeof(error)));assert(htb_negative_refract(&out,&v,&n));double before=13,after=pow(htb_scalar_get_approx(&out.x),2)+pow(htb_scalar_get_approx(&out.y),2);assert(fabs(before-after)<1e-12);
    htb_scalar area;htb_scalar_init(&ctx,&area);assert(tiling.definition->ops.tile_measure(&tiling,&location.tile,HTB_MEASURE_REFERENCE_EUCLIDEAN_AREA,&area,error,sizeof(error)));assert(htb_scalar_compare_si(&area,1)==HTB_CMP_EQUAL);htb_scalar_clear(&area);
    htb_vec2 center;htb_vec2_init(&ctx,&center);double disk_area=0,disk_area_error=0;assert(tiling.definition->ops.tile_center(&tiling,&location.tile,&center,error,sizeof(error)));assert(tiling.definition->ops.disk_area_approx(&tiling,&location.tile,&disk_area,&disk_area_error,error,sizeof(error)));assert(disk_area>0&&isfinite(disk_area));assert(disk_area_error>=0&&isfinite(disk_area_error));htb_vec2_clear(&center);
    htb_adjacency_list_clear(&neighbors);htb_point_location_clear(&location);htb_vec2_clear(&reference);htb_vec2_clear(&disk);htb_vec2_clear(&roundtrip);htb_vec2_clear(&n);htb_vec2_clear(&v);htb_vec2_clear(&out);htb_tiling_clear(&tiling);htb_arith_ctx_clear(&ctx);
}

static void base_request(htb_run_request*r,const char*du,const char*dv){memset(r,0,sizeof(*r));snprintf(r->run_id,sizeof(r->run_id),"native-test");r->backend=HTB_BACKEND_CALCIUM;configure_tiling(&r->tiling,"1/2","1/2");r->initial_precision=256;r->max_precision=2048;r->memory_limit_mb=1024;r->trajectory_count=1;htb_trajectory_input*in=&r->trajectories[0];snprintf(in->id,sizeof(in->id),"A");snprintf(in->start_u,sizeof(in->start_u),"0");snprintf(in->start_v,sizeof(in->start_v),"0");snprintf(in->direction_u,sizeof(in->direction_u),"%s",du);snprintf(in->direction_v,sizeof(in->direction_v),"%s",dv);in->bounces=2;}
static void test_vertex(void){htb_run_request q;base_request(&q,"1","1");htb_run_result r;assert(htb_run(&q,&r,NULL,NULL));assert(r.trajectories[0].status==HTB_STATUS_VERTEX);assert(r.trajectories[0].event_count==0);assert(r.trajectories[0].competing_count==2);htb_run_result_clear(&r);}
static void test_near_vertex(void){const char*plus[]={"1000001/1000000","1000000000001/1000000000000","1000000000000000000000001/1000000000000000000000000"};const char*minus[]={"999999/1000000","999999999999/1000000000000","999999999999999999999999/1000000000000000000000000"};for(int k=0;k<3;k++){htb_run_request a,b;base_request(&a,"1",plus[k]);base_request(&b,"1",minus[k]);htb_run_result x,y;assert(htb_run(&a,&x,NULL,NULL));assert(htb_run(&b,&y,NULL,NULL));assert(x.trajectories[0].event_count>0&&y.trajectories[0].event_count>0);assert(strcmp(x.trajectories[0].events[0].edge.label,"top")==0);assert(strcmp(y.trajectories[0].events[0].edge.label,"right")==0);htb_run_result_clear(&x);htb_run_result_clear(&y);}}
static void test_manifest_contract(void){char error[160]={0};htb_tiling_config c;memset(&c,0,sizeof(c));snprintf(c.id,sizeof(c.id),"elliptical-square");assert(htb_tiling_config_normalize(&c,error,sizeof(error)));assert(strcmp(c.version,"1")==0);assert(c.parameter_count==2);snprintf(c.parameters[0].key,sizeof(c.parameters[0].key),"notAParameter");assert(!htb_tiling_config_normalize(&c,error,sizeof(error)));assert(strstr(error,"unknown parameter"));}

static void test_order5_provider(htb_backend_kind kind){
    htb_arith_ctx ctx;char error[256]={0};assert(htb_arith_ctx_init(&ctx,kind,256,2048,error,sizeof(error)));htb_tiling_config config;configure_order5(&config,"0","0");htb_tiling tiling;assert(htb_tiling_init(&tiling,&ctx,&config,error,sizeof(error)));
    htb_vec2 point,n,v,out;htb_vec2_init(&ctx,&point);htb_vec2_init(&ctx,&n);htb_vec2_init(&ctx,&v);htb_vec2_init(&ctx,&out);parse(&point.x,"1/10");parse(&point.y,"1/10");htb_point_location location;htb_point_location_init(&location);assert(tiling.definition->ops.locate_point(&tiling,&point,&location,error,sizeof(error)));assert(strcmp(location.tile.type,"square")==0);
    htb_adjacency_list neighbors;htb_adjacency_list_init(&neighbors);assert(htb_tiling_neighbors(&tiling,&location.tile,&neighbors,error,sizeof(error)));assert(neighbors.count==4);for(size_t i=0;i<neighbors.count;i++){htb_adjacency reverse;assert(tiling.definition->ops.adjacent(&tiling,&neighbors.items[i].neighbor,&neighbors.items[i].neighbor_edge,&reverse,error,sizeof(error)));assert(htb_tile_id_equal(&reverse.neighbor,&location.tile));assert(strcmp(reverse.source_edge.boundary_key,neighbors.items[i].source_edge.boundary_key)==0);}
    parse(&v.x,"2");parse(&v.y,"3");assert(tiling.definition->ops.normal_at(&tiling,&neighbors.items[0].source_edge,&point,&n,error,sizeof(error)));assert(htb_negative_refract(&out,&v,&n));double after=pow(htb_scalar_get_approx(&out.x),2)+pow(htb_scalar_get_approx(&out.y),2);assert(fabs(13-after)<1e-10);
    htb_vec2 center;htb_vec2_init(&ctx,&center);double disk_area=0,disk_area_error=0;assert(tiling.definition->ops.tile_center(&tiling,&location.tile,&center,error,sizeof(error)));assert(tiling.definition->ops.disk_area_approx(&tiling,&location.tile,&disk_area,&disk_area_error,error,sizeof(error)));assert(disk_area>0&&isfinite(disk_area));assert(disk_area_error>=0&&isfinite(disk_area_error));htb_vec2_clear(&center);
    htb_adjacency_list_clear(&neighbors);htb_point_location_clear(&location);htb_vec2_clear(&point);htb_vec2_clear(&n);htb_vec2_clear(&v);htb_vec2_clear(&out);htb_tiling_clear(&tiling);htb_arith_ctx_clear(&ctx);
}

static void random_walk_request(htb_run_request*r,int order5){
    memset(r,0,sizeof(*r));snprintf(r->run_id,sizeof(r->run_id),"walk-test");r->simulation_kind=HTB_SIMULATION_RANDOM_WALK;if(order5)configure_order5(&r->tiling,"0","0");else configure_tiling(&r->tiling,"0","0");snprintf(r->walk.start_u,sizeof(r->walk.start_u),"1/10");snprintf(r->walk.start_v,sizeof(r->walk.start_v),"-1/5");snprintf(r->walk.seed,sizeof(r->walk.seed),"42");snprintf(r->walk.distribution,sizeof(r->walk.distribution),"euclidean-area-neighborhood");r->walk.steps=30;
}
static int graph_degree(const htb_walk_result*w,int node){int degree=0;for(size_t i=0;i<w->edge_count;i++)if(w->edges[i].source==node||w->edges[i].target==node)degree++;return degree;}
static int graph_node(const htb_walk_result*w,const htb_tile_id*tile){for(size_t i=0;i<w->node_count;i++)if(htb_tile_id_equal(&w->nodes[i].tile,tile))return(int)i;return-1;}
static int graph_has_edge(const htb_walk_result*w,int a,int b){if(a>b){int t=a;a=b;b=t;}for(size_t i=0;i<w->edge_count;i++)if(w->edges[i].source==a&&w->edges[i].target==b)return 1;return 0;}
static void assert_walk_valid(const htb_walk_result*w,int requested){
    assert(w->status==HTB_STATUS_COMPLETED);assert(w->completed_steps==requested);assert(w->step_count==(size_t)requested+1);assert(w->unique_tiles>=1);assert(w->unique_tiles+w->repeated_visits==requested+1);assert(w->node_count>=(size_t)w->unique_tiles);
    for(size_t i=0;i<w->step_count;i++){const htb_walk_step*s=&w->steps[i];assert(s->index==(int)i);assert(s->tile_area>0&&isfinite(s->tile_area));assert(s->tile_area_error>=0&&isfinite(s->tile_area_error));assert(s->selected_probability>0&&s->selected_probability<=1);assert(s->disk_displacement>=0);assert(s->cumulative_length>=0);if(i&&s->stayed)assert(htb_tile_id_equal(&s[-1].tile,&s->tile));}
    for(size_t i=0;i<w->node_count;i++)if(w->nodes[i].visited){int expected=strncmp(w->nodes[i].tile.key,"binary:",7)==0?5:4;assert(graph_degree(w,(int)i)==expected);}
    for(size_t i=1;i<w->step_count;i++){int a=graph_node(w,&w->steps[i-1].tile),b=graph_node(w,&w->steps[i].tile);assert(a>=0&&b>=0);if(a!=b)assert(graph_has_edge(w,a,b));}
}
static void test_random_walk(void){
    htb_run_request q;random_walk_request(&q,0);htb_run_result a,b;assert(htb_run(&q,&a,NULL,NULL));assert(htb_run(&q,&b,NULL,NULL));assert_walk_valid(&a.walk,q.walk.steps);assert_walk_valid(&b.walk,q.walk.steps);assert(a.walk.step_count==b.walk.step_count);for(size_t i=0;i<a.walk.step_count;i++){assert(htb_tile_id_equal(&a.walk.steps[i].tile,&b.walk.steps[i].tile));assert(a.walk.steps[i].random_draw==b.walk.steps[i].random_draw);assert(a.walk.steps[i].selected_probability==b.walk.steps[i].selected_probability);}htb_run_result_clear(&a);htb_run_result_clear(&b);
    random_walk_request(&q,1);q.walk.steps=12;assert(htb_run(&q,&a,NULL,NULL));assert_walk_valid(&a.walk,q.walk.steps);htb_run_result_clear(&a);
}

static void test_order5_vertex_valence(void){
    htb_arith_ctx ctx;char error[256]={0};assert(htb_arith_ctx_init(&ctx,HTB_BACKEND_CALCIUM,256,1024,error,sizeof(error)));htb_tiling_config config;configure_order5(&config,"1/10","-1/5");htb_tiling tiling;assert(htb_tiling_init(&tiling,&ctx,&config,error,sizeof(error)));
    htb_vec2 vertex;htb_vec2_init(&ctx,&vertex);parse(&vertex.x,"1/10");parse(&vertex.y,"-1/5");htb_point_location location;htb_point_location_init(&location);assert(tiling.definition->ops.locate_point(&tiling,&vertex,&location,error,sizeof(error)));assert(location.incident_edges.count==2);htb_tile_id first=location.tile,current=first;char previous[HTB_TILING_KEY_MAX]={0};
    for(int step=0;step<5;step++){htb_edge_list edges;htb_edge_list_init(&edges);assert(tiling.definition->ops.enumerate_edges(&tiling,&current,&edges,error,sizeof(error)));int found=0;htb_adjacency next;
        for(size_t i=0;i<edges.count;i++){htb_vec2 a,b,ra,rb;htb_vec2_init(&ctx,&a);htb_vec2_init(&ctx,&b);htb_vec2_init(&ctx,&ra);htb_vec2_init(&ctx,&rb);assert(tiling.definition->ops.edge_vertices(&tiling,&current,&edges.items[i],&a,&b,&ra,&rb,error,sizeof(error)));double au=htb_scalar_get_approx(&a.x),av=htb_scalar_get_approx(&a.y),bu=htb_scalar_get_approx(&b.x),bv=htb_scalar_get_approx(&b.y);int incident=hypot(au-.1,av+.2)<1e-12||hypot(bu-.1,bv+.2)<1e-12;if(incident&&strcmp(edges.items[i].boundary_key,previous)!=0){assert(tiling.definition->ops.adjacent(&tiling,&current,&edges.items[i],&next,error,sizeof(error)));snprintf(previous,sizeof(previous),"%s",edges.items[i].boundary_key);found=1;htb_vec2_clear(&a);htb_vec2_clear(&b);htb_vec2_clear(&ra);htb_vec2_clear(&rb);break;}htb_vec2_clear(&a);htb_vec2_clear(&b);htb_vec2_clear(&ra);htb_vec2_clear(&rb);}
        assert(found);current=next.neighbor;htb_edge_list_clear(&edges);
    }
    assert(htb_tile_id_equal(&current,&first));htb_point_location_clear(&location);htb_vec2_clear(&vertex);htb_tiling_clear(&tiling);htb_arith_ctx_clear(&ctx);
}

static void test_binary_provider(htb_backend_kind kind){
    htb_arith_ctx ctx;char error[256]={0};assert(htb_arith_ctx_init(&ctx,kind,256,2048,error,sizeof(error)));htb_tiling_config config;configure_binary(&config);htb_tiling tiling;assert(htb_tiling_init(&tiling,&ctx,&config,error,sizeof(error)));
    htb_vec2 reference,disk,roundtrip;htb_vec2_init(&ctx,&reference);htb_vec2_init(&ctx,&disk);htb_vec2_init(&ctx,&roundtrip);parse(&reference.x,"1/2");parse(&reference.y,"3/2");assert(tiling.definition->ops.from_reference(&tiling,&reference,&disk,error,sizeof(error)));assert(fabs(htb_scalar_get_approx(&disk.x)-3.0/13.0)<1e-14);assert(fabs(htb_scalar_get_approx(&disk.y)+2.0/13.0)<1e-14);assert(tiling.definition->ops.to_reference(&tiling,&disk,&roundtrip,error,sizeof(error)));assert(fabs(htb_scalar_get_approx(&roundtrip.x)-.5)<1e-14);assert(fabs(htb_scalar_get_approx(&roundtrip.y)-1.5)<1e-14);
    htb_point_location location;htb_point_location_init(&location);assert(tiling.definition->ops.locate_point(&tiling,&disk,&location,error,sizeof(error)));assert(strcmp(location.tile.key,"binary:0,0")==0);assert(location.incident_edges.count==0);htb_adjacency_list neighbors;htb_adjacency_list_init(&neighbors);assert(htb_tiling_neighbors(&tiling,&location.tile,&neighbors,error,sizeof(error)));assert(neighbors.count==5);for(size_t i=0;i<neighbors.count;i++){htb_adjacency back;assert(tiling.definition->ops.adjacent(&tiling,&neighbors.items[i].neighbor,&neighbors.items[i].neighbor_edge,&back,error,sizeof(error)));assert(htb_tile_id_equal(&back.neighbor,&location.tile));assert(strcmp(back.source_edge.boundary_key,neighbors.items[i].source_edge.boundary_key)==0);}
    htb_vec2 center;htb_vec2_init(&ctx,&center);double area=0,area_error=0;assert(tiling.definition->ops.tile_center(&tiling,&location.tile,&center,error,sizeof(error)));assert(fabs(htb_scalar_get_approx(&center.x)-3.0/13.0)<1e-14);assert(fabs(htb_scalar_get_approx(&center.y)+2.0/13.0)<1e-14);assert(tiling.definition->ops.disk_area_approx(&tiling,&location.tile,&area,&area_error,error,sizeof(error)));assert(area>0&&isfinite(area)&&area_error>=0);
    htb_scalar reference_area;htb_scalar_init(&ctx,&reference_area);assert(tiling.definition->ops.tile_measure(&tiling,&location.tile,HTB_MEASURE_REFERENCE_EUCLIDEAN_AREA,&reference_area,error,sizeof(error)));assert(htb_scalar_compare_si(&reference_area,1)==HTB_CMP_EQUAL);htb_scalar_clear(&reference_area);
    parse(&reference.x,"-1/2");parse(&reference.y,"3/2");assert(tiling.definition->ops.from_reference(&tiling,&reference,&disk,error,sizeof(error)));htb_point_location_clear(&location);htb_point_location_init(&location);assert(tiling.definition->ops.locate_point(&tiling,&disk,&location,error,sizeof(error)));assert(strcmp(location.tile.key,"binary:0,-1")==0);htb_edge_list edges;htb_edge_list_init(&edges);assert(tiling.definition->ops.enumerate_edges(&tiling,&location.tile,&edges,error,sizeof(error)));htb_adjacency parent;assert(tiling.definition->ops.adjacent(&tiling,&location.tile,&edges.items[2],&parent,error,sizeof(error)));assert(strcmp(parent.neighbor.key,"binary:1,-1")==0);assert(parent.neighbor_edge.local_index==4);htb_edge_list_clear(&edges);
    htb_vec2_clear(&center);htb_adjacency_list_clear(&neighbors);htb_point_location_clear(&location);htb_vec2_clear(&reference);htb_vec2_clear(&disk);htb_vec2_clear(&roundtrip);htb_tiling_clear(&tiling);htb_arith_ctx_clear(&ctx);
}

static void test_binary_vertex_incidence(void){
    htb_arith_ctx ctx;char error[256]={0};assert(htb_arith_ctx_init(&ctx,HTB_BACKEND_CALCIUM,256,2048,error,sizeof(error)));htb_tiling_config config;configure_binary(&config);htb_tiling tiling;assert(htb_tiling_init(&tiling,&ctx,&config,error,sizeof(error)));htb_vec2 reference,disk;htb_vec2_init(&ctx,&reference);htb_vec2_init(&ctx,&disk);htb_point_location location;htb_point_location_init(&location);
    parse(&reference.x,"1/2");parse(&reference.y,"1");assert(tiling.definition->ops.from_reference(&tiling,&reference,&disk,error,sizeof(error)));assert(tiling.definition->ops.locate_point(&tiling,&disk,&location,error,sizeof(error)));assert(strcmp(location.tile.key,"binary:0,0")==0);assert(location.incident_edges.count==2);assert(location.incident_edges.items[0].local_index==3);assert(location.incident_edges.items[1].local_index==4);
    htb_point_location_clear(&location);htb_point_location_init(&location);parse(&reference.x,"0");assert(tiling.definition->ops.from_reference(&tiling,&reference,&disk,error,sizeof(error)));assert(tiling.definition->ops.locate_point(&tiling,&disk,&location,error,sizeof(error)));assert(location.incident_edges.count==2);assert(location.incident_edges.items[0].local_index==0);assert(location.incident_edges.items[1].local_index==3);
    htb_point_location_clear(&location);htb_vec2_clear(&reference);htb_vec2_clear(&disk);htb_tiling_clear(&tiling);htb_arith_ctx_clear(&ctx);
}

static void test_binary_runs(void){
    htb_run_request q;memset(&q,0,sizeof(q));snprintf(q.run_id,sizeof(q.run_id),"binary-billiard");q.backend=HTB_BACKEND_ARB;configure_binary(&q.tiling);q.initial_precision=128;q.max_precision=2048;q.memory_limit_mb=1024;q.trajectory_count=1;snprintf(q.trajectories[0].id,sizeof(q.trajectories[0].id),"A");snprintf(q.trajectories[0].start_u,sizeof(q.trajectories[0].start_u),"3/13");snprintf(q.trajectories[0].start_v,sizeof(q.trajectories[0].start_v),"-2/13");snprintf(q.trajectories[0].direction_u,sizeof(q.trajectories[0].direction_u),"1");snprintf(q.trajectories[0].direction_v,sizeof(q.trajectories[0].direction_v),"1/3");q.trajectories[0].bounces=8;htb_run_result result;assert(htb_run(&q,&result,NULL,NULL));assert(result.trajectories[0].status==HTB_STATUS_COMPLETED);assert(result.trajectories[0].completed_bounces==8);for(size_t i=0;i<result.trajectories[0].event_count;i++)assert(strncmp(result.trajectories[0].events[i].tile_after.key,"binary:",7)==0);htb_run_result_clear(&result);
    random_walk_request(&q,0);configure_binary(&q.tiling);snprintf(q.walk.start_u,sizeof(q.walk.start_u),"3/13");snprintf(q.walk.start_v,sizeof(q.walk.start_v),"-2/13");q.walk.steps=12;assert(htb_run(&q,&result,NULL,NULL));assert_walk_valid(&result.walk,12);for(size_t i=0;i<result.walk.step_count;i++)assert(strncmp(result.walk.steps[i].tile.key,"binary:",7)==0);htb_run_result_clear(&result);
}

int main(void){assert(htb_tiling_definition_count()==3);const htb_tiling_definition*d=htb_tiling_definition_find("elliptical-square"),*q=htb_tiling_definition_find("order5-square"),*b=htb_tiling_definition_find("binary");assert(d&&d->tile_type_count==1&&d->tile_types[0].side_count==4);assert(q&&q->tile_type_count==1&&q->tile_types[0].side_count==4);assert(b&&b->tile_type_count==1&&b->tile_types[0].side_count==5);test_manifest_contract();test_tiling_provider(HTB_BACKEND_ARB);test_tiling_provider(HTB_BACKEND_CALCIUM);test_order5_provider(HTB_BACKEND_ARB);test_order5_provider(HTB_BACKEND_CALCIUM);test_binary_provider(HTB_BACKEND_ARB);test_binary_provider(HTB_BACKEND_CALCIUM);test_binary_vertex_incidence();test_order5_vertex_valence();test_vertex();test_near_vertex();test_random_walk();test_binary_runs();puts("native core tests passed");return 0;}
